#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long power(long long base, int exp, long long mod) {
    long long res = 1LL;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long choose(int n, int k, const vector<long long>& fact) {
    long long denom = (fact[k] * fact[n - k]) % MOD;
    long long denomInv = power(denom, (int)(MOD - 2), MOD);
    return (fact[n] * denomInv) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long K;
    cin >> N >> K;

    if (K >= N) {
        cout << 0 << "\n";
        return 0;
    }
    int C = N - (int)K;

    vector<long long> fact(200001);
    fact[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        fact[i] = (i * fact[i - 1]) % MOD;
    }

    long long totalSum = 0;
    int signFlag = 1;
    for (int i = C; i > 0; i--) {
        long long val = (choose(C, i, fact) * power(i, N, MOD)) % MOD;
        totalSum = (totalSum + signFlag * val + 2 * MOD) % MOD;
        signFlag *= -1;
    }

    long long multFactor = 2 * choose(N, C, fact);
    if (C == N)
        multFactor = 1LL;
    cout << (totalSum * multFactor) % MOD << "\n";

    return 0;
}

